from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM
from exo.core.extern import Extern, _EErr


class _Min(Extern):
    def __init__(self):
        super().__init__("min")

    def typecheck(self, args):
        if len(args) != 2:
            raise _EErr(f"expected 2 arguments, got {len(args)}")

        if args[0].type != args[1].type:
            raise _EErr(
                f"expected both arguments to have the same type, "
                f"but got {args[0].type} and {args[1].type}"
            )

        return args[0].type

    def compile(self, args, prim_type):
        # Emit a branch-free C expression computing the minimum of the two
        # arguments. This keeps the data-dependent conditional outside Exo.
        return f"(({prim_type})(({args[0]} < {args[1]}) ? {args[0]} : {args[1]}))"

    def globl(self, prim_type):
        # No additional global code needed for this extern.
        return ""

    def interpret(self, args):
        # Python-side semantics for Exo's interpreter.
        return args[0] if args[0] < args[1] else args[1]


# Extern min operator usable inside Exo kernels.
min = _Min()


@proc
def kernel_floyd_warshall(
    n: size,
    path: DATA_TYPE[n, n] @ DRAM,
):
    # Baseline Floyd-Warshall: O(n^3) triple-nested loop.
    for k in seq(0, n):
        for i in seq(0, n):
            for j in seq(0, n):
                path[i, j] = min(path[i, j], path[i, k] + path[k, j])


# ---------------------------------------------------------------------------
# Scheduling: improve data locality and vectorization.
#
# Strategy:
#   1. Split the innermost j loop by a small factor (4), then unroll it to
#      expose instruction-level parallelism and encourage SIMD vectorization.
#   2. Tile the i loop (factor 32) to improve cache locality when traversing
#      rows of the path matrix. This preserves the original k–i–j ordering.
#   3. Simplify to clean up index arithmetic.
# ---------------------------------------------------------------------------

# Start from the baseline kernel.
p = kernel_floyd_warshall

# 1) Tile the j loop with factor 4 and create a fixed-size inner loop "ji".
#    The "cut" tail strategy keeps a separate cleanup loop for remainders.
p = divide_loop(p, "j", 4, ("jo", "ji"), tail="cut")

# 2) Unroll the inner j loop of constant extent (4). This reduces loop
#    overhead and gives the backend more opportunities for vectorization.
p = unroll_loop(p, "ji")

# 3) Tile the i loop with factor 32 ("io" outer, "ii" inner). This improves
#    spatial locality over rows of the path matrix without reordering
#    iterations across different k values.
p = divide_loop(p, "i", 32, ("io", "ii"), tail="cut")

