#    eliminate trivial loops/conditions introduced by the tiling transforms.
p = simplify(p)

# Use the optimized schedule as the exported kernel. The procedure name
# remains "kernel_floyd_warshall", so the generated C symbol matches the
# declaration in generated/floyd-warshall/floyd-warshall.h.
kernel_floyd_warshall = p
